    "contracts/interfaces/IPropAMM.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity >=0.8.25;

/// @title IPropAMM
/// @notice Interface a proprietary AMM must implement to be added to the
/// `PropAMMRouter` whitelist.
/// @dev The router uses a push-payment model: before calling `swap` it
/// transfers `amountIn` of `tokenIn` to the propAMM, then `swap` is expected to
/// consume that balance.
interface IPropAMM {
    /// @notice Emitted once per successful swap after `tokenOut` is delivered to `recipient`.
    /// @param sender The address that invoked the swap entrypoint and supplied
    /// `amountIn` of `tokenIn`. Indexed so consumers can fetch a given account's
    /// recent swaps.
    /// @param tokenIn The token sold.
    /// @param tokenOut The token bought.
    /// @param amountIn The exact amount of `tokenIn` pulled from `sender`.
    /// @param amountOut The amount of `tokenOut` delivered to `recipient`,
    /// measured as a balance delta.
    /// @param recipient The address that received `tokenOut`.
    event Swapped(
        address indexed sender,
        address indexed tokenIn,
        address indexed tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        address recipient
    );

    /// @notice A token pair a propAMM supports.
    struct TokenPair {
        address token0;
        address token1;
    }

    /// @notice Returns true if the propAMM can swap `tokenIn` for `tokenOut` in
    /// the current block.
    /// @dev A `view` fast-path the router can use to skip inactive propAMMs before
    /// paying for a full `quote`. Reported per-pair so a propAMM can be live for
    /// some pairs and not others.
    /// @param tokenIn The address of the token being sold.
    /// @param tokenOut The address of the token being bought.
    /// @return active True if a swap for the pair would succeed right now.
    function isActive(
        address tokenIn,
        address tokenOut
    ) external view returns (bool active);

    /// @notice Returns all token pairs the propAMM support, both active and inactive.
    /// @dev Advisory, for off-chain discovery; the router does not call this on
    /// its swap path.
    /// @return pairs The supported pairs.
    function getPairs() external view returns (TokenPair[] memory pairs);

    /// @notice Quotes `amountIn` of `tokenIn` and returns the `tokenOut` amount
    /// a swap would deliver.
    /// @dev MUST revert if the propAMM is inactive for the pair.
    /// MUST NOT require a `tokenIn` balance or allowance from the caller.
    /// @param tokenIn The address of the token being sold.
    /// @param tokenOut The address of the token being bought.
    /// @param amountIn The exact amount of `tokenIn` to quote against.
    /// @return amountOut The amount of `tokenOut` the swap would deliver.
    function quote(
        address tokenIn,
        address tokenOut,
        uint256 amountIn
    ) external returns (uint256 amountOut);

    /// @notice Swaps an exact `amountIn` of `tokenIn` for as much `tokenOut` as
    /// possible, delivering it to `recipient`.
    /// @dev Expects `amountIn` of `tokenIn` to have ALREADY been transferred to
    /// the propAMM by the caller (push-payment).
    /// SHALL revert if it cannot deliver at least `minAmountOut` of `tokenOut`
    /// to `recipient`. The Router makes that check too.
    /// @param tokenIn The address of the token being sold.
    /// @param tokenOut The address of the token being bought.
    /// @param amountIn The exact amount of `tokenIn` to sell.
    /// @param minAmountOut The minimum acceptable amount of `tokenOut`.
    /// @param recipient The address that will receive `tokenOut`.
    /// @param deadline Unix timestamp after which the swap is no longer valid.
    /// This value can safely be ignored if coming from the Router, since it
    /// already does the check.
    /// @return amountOut The amount of `tokenOut` received by `recipient`.
    function swap(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        address recipient,
        uint256 deadline
    ) external returns (uint256 amountOut);
}"
    },
    "contracts/interfaces/IPropAMMExactOut.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity >=0.8.25;

import "./IPropAMM.sol";
import "@openzeppelin/contracts/utils/introspection/IERC165.sol";

/// @title IPropAMMExactOut
/// @notice Optional extension of {IPropAMM} for proprietary AMMs that also
/// support exact-output swaps: the caller fixes the exact `amountOut` of
/// `tokenOut` it wants and a ceiling `amountInMax` on what it will spend.
/// @dev Inherits the full exact-input surface (`isActive`, `getPairs`, `quote`,
/// `swap`), the `TokenPair` struct, and the `Swapped` event from {IPropAMM}, so
/// a venue implementing this interface supports BOTH exact-input and
/// exact-output. The router uses the same push-payment model as exact-input,
/// but because the input amount is not known up front it transfers
/// `amountInMax` and the venue MUST refund the unspent remainder (see
/// `swapExactOut`).
///
/// Because exact-output is optional, this interface also inherits {IERC165} so
/// the router and off-chain integrators can detect support at runtime without a
/// trial swap — e.g. `ERC165Checker.supportsInterface(venue,
/// type(IPropAMMExactOut).interfaceId)`. A conforming venue MUST report `true`
/// from `supportsInterface` for `type(IERC165).interfaceId`,
/// `type(IPropAMM).interfaceId`, and `type(IPropAMMExactOut).interfaceId`.
/// Note `type(IPropAMMExactOut).interfaceId` covers only the exact-output
/// selectors declared here (Solidity excludes inherited functions), so it is
/// distinct from `type(IPropAMM).interfaceId`. Plain exact-input venues that do
/// not implement ERC165 are still supported: an `ERC165Checker` probe returns
/// `false` for them rather than reverting.
interface IPropAMMExactOut is IPropAMM, IERC165 {
    /// @notice Quotes the `tokenIn` amount required to receive an exact
    /// `amountOut` of `tokenOut`.
    /// @dev The exact-output mirror of {IPropAMM-quote}: it inverts the
    /// known/unknown sides, fixing `amountOut` and returning the required
    /// `amountIn`. MUST revert if the propAMM is inactive for the pair.
    /// MUST NOT require a `tokenIn` balance or allowance from the caller.
    /// @param tokenIn The address of the token being sold.
    /// @param tokenOut The address of the token being bought.
    /// @param amountOut The exact amount of `tokenOut` to receive.
    /// @return amountIn The amount of `tokenIn` the swap would require.
    function quoteExactOut(address tokenIn, address tokenOut, uint256 amountOut) external returns (uint256 amountIn);

    /// @notice Swaps as little `tokenIn` as needed to deliver an exact
    /// `amountOut` of `tokenOut` to `recipient`, spending at most `amountInMax`.
    /// @dev Push-payment: the caller transfers `amountInMax` of `tokenIn` to the
    /// propAMM BEFORE this call. The propAMM:
    ///  - MUST deliver exactly `amountOut` of `tokenOut` to `recipient`;
    ///  - MUST consume at most `amountInMax` of `tokenIn`, and SHALL revert if
    ///    delivering `amountOut` would require more;
    ///  - MUST refund any unspent `tokenIn` (`amountInMax - amountIn`) to
    ///    `refundRecipient`.
    /// SHALL revert if the pair is inactive. The `deadline` can safely be
    /// ignored when coming from the Router, since it already does the check.
    /// @param tokenIn The address of the token being sold.
    /// @param tokenOut The address of the token being bought.
    /// @param amountOut The exact amount of `tokenOut` to deliver to `recipient`.
    /// @param amountInMax The maximum amount of `tokenIn` the caller will spend;
    /// also the amount the caller pushes to the propAMM up front.
    /// @param recipient The address that will receive `tokenOut`.
    /// @param refundRecipient The address to refund the unspent `tokenIn` to.
    /// @param deadline Unix timestamp after which the swap is no longer valid.
    /// @return amountIn The amount of `tokenIn` actually consumed by the swap.
    function swapExactOut(
        address tokenIn,
        address tokenOut,
        uint256 amountOut,
        uint256 amountInMax,
        address recipient,
        address refundRecipient,
        uint256 deadline
    ) external returns (uint256 amountIn);
}
"
